SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, (COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) - 1) / NULLIF(COUNT(p.subject_id), 0) * (COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) - COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END)) / NULLIF(COUNT(p.subject_id), 0) AS ci, AVG(CASE WHEN p.dod IS NOT NULL THEN (p.dischtime - p.admittime) END) AS avg_los FROM physionet-data.mimiciv_3_1_hosp.patients p JOIN physionet-data.mimiciv_3_1_hosp.admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 55 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2020 AND p.anchor_year_group BETWEEN 50 AND 60 AND p.dod IS NOT NULL AND a.admission_type_id != 757071 GROUP BY a.los;